UPDATE teacher_rules_relay SET urgency = :urgency, tone = :tone, must_info = :must_info, facts = :facts, keywords = :keywords, rounds = CAST(:rounds AS INTEGER), deadline = :deadline, student = :student, subject_id = CASE WHEN :new_sid = '' THEN subject_id ELSE CAST(:new_sid AS INTEGER) END, author = :author, updated_at = datetime('now', 'localtime') WHERE id = CAST(:id AS INTEGER) AND (subject_id = CAST(:subj AS INTEGER) OR subject_id = 0)
